with scored as (select *, round(credit_limit / sum(credit_limit) over (partition by segment, city), 4) as credit_limit_share, first_value(segment) ignore nulls over (partition by country order by signup_date, id rows between unbounded preceding and current row) as first_known_segment, ntile(5) over (partition by city order by age, id) as age_bucket from customers) select city, size(collect_set(segment)) as num_segments, count(distinct id) as distinct_ids, sort_array(collect_set(segment)) as segment_list from scored group by city having distinct_ids >= 1 order by city nulls last;
